/// `remove_owned` with a hook that runs between the first check and the
/// rename-aside (tests use it to change the copy in that window).
fn remove_owned_at(
    dst: &Path,
    expect: &OwnedExpectation,
    trash: &Path,
    before_rename: &dyn Fn(),
) -> Result<RemoveOutcome> {
    let want_hash = expect.strategy == Strategy::Copy;
    let seen = observe_path(dst, want_hash)?;
    if seen == ObservedKind::Missing {
        return Ok(RemoveOutcome::Skipped(SkipReason::Missing));
    }
    match expect.strategy {
        Strategy::Symlink => {
            let ObservedKind::Symlink { target, .. } = &seen else {
                return Ok(RemoveOutcome::Skipped(SkipReason::Foreign));
            };
            if *target != expect.source {
                return Ok(RemoveOutcome::Skipped(SkipReason::Modified));
            }
            match observe_path(dst, false)? {
                ObservedKind::Symlink { target, .. } if target == expect.source => {}
                _ => return Ok(RemoveOutcome::Skipped(SkipReason::Modified)),
            }
            std::fs::remove_file(dst)
                .map_err(io_err(format!("cannot remove link {}", dst.display())))?;
            let _ = sync_dir(parent_of(dst));
            Ok(RemoveOutcome::Removed)
        }
        Strategy::Copy => {
            let ObservedKind::Dir { tree_hash: got } = &seen else {
                return Ok(RemoveOutcome::Skipped(SkipReason::Foreign));
            };
            let Some(want) = &expect.tree_hash else {
                return Ok(RemoveOutcome::Skipped(SkipReason::Modified));
            };
            if got.as_ref() != Some(want) {
                return Ok(RemoveOutcome::Skipped(SkipReason::Modified));
            }
            std::fs::create_dir_all(trash)
                .map_err(io_err(format!("cannot create {}", trash.display())))?;
            let item = trash.join(file_name_text(dst)?);
            before_rename();
            match std::fs::rename(dst, &item) {
                Ok(()) => {}
                Err(e) if rename_aside_skip(e.kind()).is_some() => {
                    let _ = std::fs::remove_dir(trash);
                    return Ok(RemoveOutcome::Skipped(SkipReason::CrossDevice));
                }
                Err(e) => {
                    return Err(Error::io(format!("cannot move {} aside", dst.display()), e));
                }
            }
            let again = tree_hash(&item, SKILL_SKIP_NAMES)?;
            if again != *want {
                if observe_path(dst, false)? == ObservedKind::Missing {
                    std::fs::rename(&item, dst)
                        .map_err(io_err(format!("cannot move {} back", dst.display())))?;
                    let _ = std::fs::remove_dir(trash);
                }
                return Ok(RemoveOutcome::Skipped(SkipReason::Modified));
            }
            let residue = delete_manifest(&item)?;
            let _ = std::fs::remove_dir(trash);
            if residue {
                Ok(RemoveOutcome::RemovedWithResidue { trash: item })
            } else {
                Ok(RemoveOutcome::Removed)
            }
        }
    }
}

/// Delete what the hash covered inside a trash copy (G9): a pruned lstat
/// walk (`SKILL_SKIP_NAMES` are never descended into or listed), regular
/// files and symlinks unlinked, a `.DS_Store` unlinked only when it is a
/// regular file, then directories removed bottom-up. Returns true when
/// anything is left (residue).
fn delete_manifest(item: &Path) -> Result<bool> {
    let mut residue = false;
    let mut dirs: Vec<PathBuf> = vec![item.to_path_buf()];
    let mut stack: Vec<PathBuf> = vec![item.to_path_buf()];
    while let Some(dir) = stack.pop() {
        let rd =
            std::fs::read_dir(&dir).map_err(io_err(format!("cannot read {}", dir.display())))?;
        for entry in rd {
            let entry = entry.map_err(io_err(format!("cannot read {}", dir.display())))?;
            let path = entry.path();
            let name = entry.file_name().to_string_lossy().into_owned();
            let meta = std::fs::symlink_metadata(&path)
                .map_err(io_err(format!("cannot inspect {}", path.display())))?;
            let ft = meta.file_type();
            if SKILL_SKIP_NAMES.contains(&name.as_str()) {
                if name == ".DS_Store" && ft.is_file() {
                    std::fs::remove_file(&path)
                        .map_err(io_err(format!("cannot remove {}", path.display())))?;
                } else {
                    residue = true;
                }
                continue;
            }
            if ft.is_symlink() || ft.is_file() {
                std::fs::remove_file(&path)
                    .map_err(io_err(format!("cannot remove {}", path.display())))?;
            } else if ft.is_dir() {
                dirs.push(path.clone());
                stack.push(path);
            } else {
                residue = true;
            }
        }
    }
    dirs.sort_by_key(|d| std::cmp::Reverse(d.components().count()));
    for d in dirs {
        match std::fs::remove_dir(&d) {
            Ok(()) => {}
            Err(e) if e.kind() == ErrorKind::DirectoryNotEmpty => residue = true,
            Err(e) => return Err(Error::io(format!("cannot remove {}", d.display()), e)),
        }
    }
    Ok(residue)
}

fn list_source(root: &Path, canonical_root: &Path) -> Result<Vec<SrcEntry>> {
    let mut out = Vec::new();
    let mut stack: Vec<(PathBuf, String)> = vec![(root.to_path_buf(), String::new())];
    while let Some((dir, rel)) = stack.pop() {
        let rd =
            std::fs::read_dir(&dir).map_err(io_err(format!("cannot read {}", dir.display())))?;
        let mut children: Vec<_> = rd
            .collect::<std::io::Result<Vec<_>>>()
            .map_err(io_err(format!("cannot read {}", dir.display())))?;
        children.sort_by_key(|e| e.file_name());
        for entry in children {
            let name = entry.file_name().to_string_lossy().into_owned();
            if SKILL_SKIP_NAMES.contains(&name.as_str()) {
                continue;
            }
            let path = entry.path();
            let child_rel = if rel.is_empty() {
                name.clone()
            } else {
                format!("{rel}/{name}")
            };
            let meta = std::fs::symlink_metadata(&path)
                .map_err(io_err(format!("cannot inspect {}", path.display())))?;
            let ft = meta.file_type();
            if ft.is_symlink() {
                let target = std::fs::read_link(&path)
                    .map_err(io_err(format!("cannot read link {}", path.display())))?;
                if !link_stays_inside(&child_rel, &target) {
                    return Err(refuse(&path, "link leaves the skill directory"));
                }
                if let Ok(resolved) = std::fs::canonicalize(&path)
                    && !resolved.starts_with(canonical_root)
                {
                    return Err(refuse(&path, "link leaves the skill directory"));
                }
                out.push(SrcEntry::Link(child_rel, target));
            } else if ft.is_dir() {
                out.push(SrcEntry::Dir(child_rel.clone()));
                stack.push((path, child_rel));
            } else if ft.is_file() {
                out.push(SrcEntry::File(child_rel));
            } else {
                return Err(refuse(&path, "special file"));
            }
        }
    }
    Ok(out)
}

fn copy_skill(src: &Path, dst: &Path, tag: &str, expect: &Hash) -> Result<Hash> {
    if observe_path(dst, false)? != ObservedKind::Missing {
        return Err(Error::io(
            format!("destination {} already exists", dst.display()),
            std::io::Error::from(ErrorKind::AlreadyExists),
        ));
    }
    let name = file_name_text(dst)?;
    let temp = parent_of(dst).join(format!("{TEMP_PREFIX}{tag}-{name}"));
    if observe_path(&temp, false)? != ObservedKind::Missing {
        return Err(Error::io(
            format!("temp path {} already exists", temp.display()),
            std::io::Error::from(ErrorKind::AlreadyExists),
        ));
    }
    let canonical_root =
        std::fs::canonicalize(src).map_err(io_err(format!("cannot resolve {}", src.display())))?;
    let entries = list_source(src, &canonical_root)?;
    let result = (|| -> Result<Hash> {
        copy_into(src, &temp, &entries)?;
        let got = tree_hash(&temp, SKILL_SKIP_NAMES)?;
        if got != *expect {
            return Err(Error::SourceChanged {
                id: src.to_string_lossy().into_owned(),
                reason: "the copied tree hash differs from the catalog hash".to_string(),
            });
        }
        if observe_path(dst, false)? != ObservedKind::Missing {
            return Err(Error::io(
                format!("destination {} appeared during the copy", dst.display()),
                std::io::Error::from(ErrorKind::AlreadyExists),
            ));
        }
        std::fs::rename(&temp, dst)
            .map_err(io_err(format!("cannot move the copy to {}", dst.display())))?;
        Ok(got)
    })();
    match result {
        Ok(h) => {
            let _ = sync_dir(parent_of(dst));
            Ok(h)
        }
        Err(e) => {
            let _ = remove_own_temp_dir(&temp);
            Err(e)
        }
    }
}

/// Remove our own temp directory `.unam-tmp-*` after lstat shows a real
/// directory (plan P30: the single recursive removal in production code).
fn remove_own_temp_dir(path: &Path) -> Result<bool> {
    let ours = path
        .file_name()
        .map(|n| n.to_string_lossy().starts_with(TEMP_PREFIX))
        .unwrap_or(false);
    if !ours {
        return Ok(false);
    }
    match std::fs::symlink_metadata(path) {
        Ok(m) if m.file_type().is_dir() => {}
        Ok(_) => return Ok(false),
        Err(e) if e.kind() == ErrorKind::NotFound => return Ok(false),
        Err(e) => return Err(Error::io(format!("cannot inspect {}", path.display()), e)),
    }
    std::fs::remove_dir_all(path).map_err(io_err(format!("cannot remove {}", path.display())))?;
    Ok(true)
}

/// The child `<root>/<name>` after `validate_dest_name`. Only a root has
/// children; the error string is the reason.
pub fn join_child(&self, name: &str) -> std::result::Result<DestPath, String> {
    if self.kind != DestKind::Root {
        return Err("only a destination root has children".to_string());
    }
    validate_dest_name(name)?;
    let mut parts = Path::new(name).components();
    match (parts.next(), parts.next()) {
        (Some(Component::Normal(_)), None) => {}
        _ => return Err("not a single path component".to_string()),
    }
    Ok(DestPath {
        path: self.path.join(name),
        rel: format!("{}/{name}", self.rel),
        kind: DestKind::Child,
    })
}

/// Validate a destination name (plan P3): non-empty, not whitespace-only,
/// at most 255 bytes, not `.` or `..`, no `/`, `\`, NUL, or other control
/// character, and not starting with `.unam-tmp-`.
pub fn validate_dest_name(name: &str) -> std::result::Result<(), String> {
    if name.is_empty() {
        return Err("empty name".to_string());
    }
    if name.trim().is_empty() {
        return Err("whitespace-only name".to_string());
    }
    if name.len() > MAX_DEST_NAME_BYTES {
        return Err("longer than 255 bytes".to_string());
    }
    if name == "." || name == ".." {
        return Err(format!("`{name}` is not allowed"));
    }
    if name.contains('/') || name.contains('\\') {
        return Err("path separator in name".to_string());
    }
    if name.chars().any(char::is_control) {
        return Err("control character in name".to_string());
    }
    if name.starts_with(TEMP_PREFIX) {
        return Err("reserved `.unam-tmp-` prefix".to_string());
    }
    Ok(())
}

/// Open the lock file read-write without truncating it (plan P5, G1). A
/// symlink (dangling or not) or any entry that is not a regular file at the
/// lock path is `StateDirInvalid` and nothing is created or opened.
pub fn open_lock_file<P: Writable>(p: &P) -> Result<File> {
    let path = p.write_target();
    match std::fs::symlink_metadata(path) {
        Ok(m) => {
            if m.file_type().is_symlink() || !m.file_type().is_file() {
                return Err(Error::StateDirInvalid {
                    path: path.to_path_buf(),
                    reason: "the lock path is a symlink or not a regular file".to_string(),
                });
            }
        }
        Err(e) if e.kind() == ErrorKind::NotFound => {}
        Err(e) => return Err(Error::io(format!("cannot inspect {}", path.display()), e)),
    }
    let parent = parent_of(path);
    if let Ok(m) = std::fs::symlink_metadata(parent)
        && !m.file_type().is_dir()
    {
        return Err(Error::StateDirInvalid {
            path: parent.to_path_buf(),
            reason: "the state directory is a symlink or not a directory".to_string(),
        });
    }
    std::fs::create_dir_all(parent).map_err(io_err(format!(
        "cannot create directory {}",
        parent.display()
    )))?;
    std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .truncate(false)
        .open(path)
        .map_err(io_err(format!("cannot open {}", path.display())))
}

/// Classify the destination root `<project_root>/<rel>` (P3): every
/// existing prefix must resolve inside the canonical project root and be a
/// directory; a symlink whose resolution stays inside is allowed.
pub fn classify_dest_root(project_root: &Path, rel: &str) -> Result<DestRootState> {
    let canon_root = canonical(project_root)?;
    let prefixes = dest_prefixes(rel);
    if prefixes.is_empty() {
        return Ok(DestRootState::NotDir);
    }
    for (i, prefix) in prefixes.iter().enumerate() {
        let p = project_root.join(prefix);
        let meta = match std::fs::symlink_metadata(&p) {
            Ok(m) => m,
            Err(e) if e.kind() == ErrorKind::NotFound => {
                return Ok(DestRootState::Missing {
                    to_create: prefixes[i..].to_vec(),
                });
            }
            Err(e) => return Err(Error::io(format!("cannot inspect {}", p.display()), e)),
        };
        if meta.file_type().is_symlink() {
            let resolved = match std::fs::canonicalize(&p) {
                Ok(r) => r,
                Err(_) => return Ok(DestRootState::NotDir),
            };
            if !resolved.starts_with(&canon_root) {
                return Ok(DestRootState::Outside {
                    resolved: resolved.to_string_lossy().into_owned(),
                });
            }
            if !resolved.is_dir() {
                return Ok(DestRootState::NotDir);
            }
        } else if !meta.file_type().is_dir() {
            return Ok(DestRootState::NotDir);
        }
    }
    // Belt and braces: the whole root resolves inside the project.
    let resolved = canonical(&project_root.join(rel))?;
    if !resolved.starts_with(&canon_root) {
        return Ok(DestRootState::Outside {
            resolved: resolved.to_string_lossy().into_owned(),
        });
    }
    Ok(DestRootState::Dir)
}

/// Read and validate the journal of `state` (the journal is untrusted).
pub fn read_journal(state: &StateDir, adapter_dest: &str) -> Result<JournalRead> {
    let path = state.journal();
    let bytes = match std::fs::read(path.path()) {
        Ok(b) => b,
        Err(e) if e.kind() == ErrorKind::NotFound => return Ok(JournalRead::Absent),
        Err(e) => {
            return Err(Error::io(
                format!("cannot read {}", path.path().display()),
                e,
            ));
        }
    };
    let invalid = |reason: String| Error::JournalInvalid {
        path: path.path().to_path_buf(),
        reason,
    };
    let text = String::from_utf8_lossy(&bytes).into_owned();
    let ends_with_newline = text.ends_with('\n');
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    let mut records: Vec<Record> = Vec::new();
    let mut valid_text = String::new();
    let mut torn_tail = false;
    for (i, raw) in lines.iter().enumerate() {
        let last = i + 1 == lines.len();
        let body = raw.strip_suffix('\n').unwrap_or(raw);
        let value: Value = match serde_json::from_str(body) {
            Ok(v) => v,
            Err(e) => {
                if last {
                    torn_tail = true;
                    break;
                }
                return Err(invalid(format!("line {} is not JSON: {e}", i + 1)));
            }
        };
        let rec: Record = serde_json::from_value(value)
            .map_err(|e| invalid(format!("line {} is not a journal record: {e}", i + 1)))?;
        valid_text.push_str(body);
        valid_text.push('\n');
        records.push(rec);
    }
    if records.is_empty() {
        return Ok(JournalRead::TornBegin);
    }
    let mut iter = records.into_iter();
    let Some(Record::Begin(begin)) = iter.next() else {
        return Err(invalid("a record comes before `begin`".into()));
    };
    let begin = *begin;
    validate_begin(&begin, state, adapter_dest).map_err(invalid)?;
    let receipt_before = match &begin.receipt_before {
        Value::Null => None,
        v => {
            let r = Receipt::from_value(v, path.path())
                .map_err(|e| invalid(format!("receipt_before: {e}")))?;
            if r.target != state.target.as_str() {
                return Err(invalid("receipt_before is for another target".into()));
            }
            if let Some(bad) = r.skill_entries().find(|e| !e.consistent(adapter_dest)) {
                return Err(invalid(format!(
                    "receipt_before entry {} has the destination {:?}",
                    bad.skill_id, bad.dest
                )));
            }
            Some(r)
        }
    };
    let count = u32::try_from(begin.plan.len()).unwrap_or(u32::MAX);
    let prefixes = dest_prefixes(&begin.dest_rel);
    let mut states: BTreeMap<u32, StepState> =
        (1..=count).map(|n| (n, StepState::Pending)).collect();
    let mut dirs: Vec<String> = Vec::new();
    let mut skipped_dirs: Vec<String> = Vec::new();
    let mut dirs_removed: Vec<String> = Vec::new();
    let mut marker = None;
    let check_n = |n: u32| -> Result<()> {
        if n == 0 || n > count {
            Err(invalid(format!("record names step {n} outside the plan")))
        } else {
            Ok(())
        }
    };
    let check_dir = |p: &str| -> Result<()> {
        if prefixes.iter().any(|x| x == p) {
            Ok(())
        } else {
            Err(invalid(format!(
                "directory {p:?} is not a destination prefix"
            )))
        }
    };
    for rec in iter {
        match rec {
            Record::Begin(_) => return Err(invalid("duplicate `begin`".into())),
            Record::Started { n } => {
                check_n(n)?;
                states.insert(n, StepState::Started);
            }
            Record::Done { n, how } => {
                check_n(n)?;
                states.insert(n, StepState::Done { how });
            }
            Record::Failed { n, code, message } => {
                check_n(n)?;
                states.insert(n, StepState::Failed { code, message });
            }
            Record::Skipped { n, reason } => {
                check_n(n)?;
                states.insert(n, StepState::Skipped { reason });
            }
            Record::Dir { path } => {
                check_dir(&path)?;
                if !dirs.contains(&path) {
                    dirs.push(path);
                }
            }
            Record::DirSkipped { path } => {
                check_dir(&path)?;
                skipped_dirs.push(path);
            }
            Record::DirRemoved { path } => {
                check_dir(&path)?;
                if !dirs_removed.contains(&path) {
                    dirs_removed.push(path);
                }
            }
            Record::Receipt { outcome } => marker = Some(outcome),
        }
    }
    let dirs_created = dirs
        .into_iter()
        .filter(|d| !skipped_dirs.contains(d))
        .collect();
    Ok(JournalRead::Present(Box::new(Journal {
        begin,
        states,
        dirs_created,
        dirs_removed,
        marker,
        torn_tail,
        ends_with_newline,
        valid_text,
        receipt_before,
    })))
}

fn validate_begin(
    b: &Begin,
    state: &StateDir,
    adapter_dest: &str,
) -> std::result::Result<(), String> {
    if b.version != 1 {
        return Err(format!("unsupported journal version {}", b.version));
    }
    if !valid_op_id(&b.op_id) {
        return Err(format!("invalid operation id {:?}", b.op_id));
    }
    if b.target != state.target.as_str() {
        return Err(format!("journal is for target {:?}", b.target));
    }
    if b.dest_rel != adapter_dest {
        return Err(format!(
            "journal destination {:?} is not {adapter_dest}",
            b.dest_rel
        ));
    }
    if b.project_root != state.root.to_string_lossy() {
        return Err(
            "journal project_root differs from this project; move the project back or roll back there"
                .to_string(),
        );
    }
    let prefixes = dest_prefixes(&b.dest_rel);
    for d in &b.dest_dirs_planned {
        if !prefixes.contains(d) {
            return Err(format!(
                "planned directory {d:?} is not a destination prefix"
            ));
        }
    }
    for (i, step) in b.plan.iter().enumerate() {
        let want = u32::try_from(i + 1).unwrap_or(u32::MAX);
        if step.n() != want {
            return Err(format!("plan step {} has number {}", i + 1, step.n()));
        }
        if let Some(name) = step.name() {
            validate_dest_name(name).map_err(|r| format!("step {want} name {name:?}: {r}"))?;
        }
        if let JournalStep::RemoveDir { dir, .. } = step
            && !prefixes.contains(dir)
        {
            return Err(format!(
                "step {want} removes {dir:?}, not a destination prefix"
            ));
        }
    }
    Ok(())
}

/// Take the project lock (P5, G1): layout check, open without
/// truncation, `try_lock`, identity check, then write one JSON line.
pub fn acquire(root: &Path, command: &str, clock: &dyn Clock) -> Result<ProjectLock> {
    check_state_layout(root, None)?;
    let path = lock_path(root);
    let mut file = crate::fsops::open_lock_file(&path)?;
    match file.try_lock() {
        Ok(()) => {}
        Err(std::fs::TryLockError::WouldBlock) => {
            return Err(Error::Locked {
                pid: read_lock_pid(path.path()),
            });
        }
        Err(std::fs::TryLockError::Error(e)) => {
            return Err(Error::io(
                format!("cannot lock {}", path.path().display()),
                e,
            ));
        }
    }
    crate::fsops::verify_lock_identity(&file, &path)?;
    let line = json!({
        "pid": std::process::id(),
        "started_at": clock.now_rfc3339(),
        "command": command,
    })
    .to_string();
    let ctx = format!("cannot write {}", path.path().display());
    file.set_len(0)
        .and_then(|()| file.rewind())
        .and_then(|()| file.write_all(format!("{line}\n").as_bytes()))
        .and_then(|()| file.sync_all())
        .map_err(|e| Error::io(ctx, e))?;
    Ok(ProjectLock { _file: file })
}

/// Apply `plan` (P9): lock and selection are the caller's; this writes the
/// `begin` record, runs every step (never stopping at a failure), then the
/// final sequence.
pub fn execute(
    ctx: &ApplyCtx<'_>,
    plan: &Plan,
    prelude: &SelectionPrelude,
    fs: &dyn FsOps,
) -> Result<ApplyReport> {
    let before = load_receipt_opt(ctx)?;
    ensure_dest_root(ctx)?;
    let begin = Begin {
        version: 1,
        op_id: plan.op_id.clone(),
        command: prelude.command.clone(),
        target: ctx.adapter.id().as_str().to_string(),
        project_root: ctx.root_text(),
        started_at: ctx.clock.now_rfc3339(),
        dest_rel: ctx.adapter.destination().to_string(),
        dest_dirs_planned: plan.dest_dirs_to_create.clone(),
        selection_before: prelude.selection_before.clone(),
        selection_after_text: prelude.selection_after_text.clone(),
        selection_after_hash: prelude.selection_after_hash.clone(),
        selection_hash: plan.selection_hash.to_string(),
        receipt_before: before.as_ref().map_or(Value::Null, Receipt::to_value),
        plan: plan.steps.iter().map(journal_step).collect(),
    };
    fs.write_state(
        &ctx.state.journal(),
        Record::Begin(Box::new(begin.clone())).to_line().as_bytes(),
    )?;
    let mut runner = Runner {
        ctx,
        fs,
        op_id: plan.op_id.clone(),
        planned_dirs: plan.dest_dirs_to_create.clone(),
        dirs_created: Vec::new(),
        dirs_removed: Vec::new(),
        new_dirs: Vec::new(),
        removed_dirs: Vec::new(),
        warnings: Vec::new(),
    };
    let dest_rel = ctx.adapter.destination();
    let mut outcomes = BTreeMap::new();
    let mut results = Vec::new();
    let mut removal_applied = false;
    for step in &plan.steps {
        runner.append(&Record::Started { n: step.n() })?;
        let outcome = runner.exec_step(step)?;
        runner.append(&terminal_record(step.n(), &outcome, "ran"))?;
        if outcome == StepOutcome::Done && is_removal(step) {
            removal_applied = true;
        }
        outcomes.insert(step.n(), outcome.clone());
        results.push(result_of(step, dest_rel, outcome));
    }
    let (receipt, status, history_written) = finish(
        ctx,
        fs,
        &begin,
        before.as_ref(),
        &plan.steps,
        &outcomes,
        &mut runner,
    )?;
    Ok(ApplyReport {
        op_id: plan.op_id.clone(),
        command: prelude.command.clone(),
        results,
        status,
        receipt,
        history_written,
        warnings: runner.warnings,
        new_dirs: runner.new_dirs,
        removed_dirs: runner.removed_dirs,
        removal_applied,
        refresh: ctx.adapter.refresh_note(ApplyContext {
            dest_root_existed: plan.dest_dirs_to_create.is_empty(),
        }),
    })
}

/// History, receipt, marker, journal removal, prune (or the partial form).
fn finish(
    ctx: &ApplyCtx<'_>,
    fs: &dyn FsOps,
    begin: &Begin,
    before: Option<&Receipt>,
    steps: &[Step],
    outcomes: &BTreeMap<u32, StepOutcome>,
    runner: &mut Runner<'_, '_>,
) -> Result<(Receipt, ApplyStatus, bool)> {
    let empty = Receipt::empty(&ctx.root, ctx.adapter.id());
    let before_r = before.unwrap_or(&empty);
    let now = ctx.clock.now_rfc3339();
    let mut receipt = build_receipt(&ReceiptUpdate {
        before: before_r,
        dest_rel: ctx.adapter.destination(),
        steps,
        outcomes,
        now: &now,
        op_id: &begin.op_id,
        selection_hash: &hash_from_text(&begin.selection_hash),
        dirs_created: &runner.dirs_created,
        dirs_removed: &runner.dirs_removed,
    });
    receipt.project_root = ctx.root_text();
    let status = status_of(outcomes);
    let mut history_written = false;
    match status {
        ApplyStatus::Applied | ApplyStatus::AppliedWithSkips => {
            let entry = HistoryEntry {
                version: 1,
                op_id: begin.op_id.clone(),
                command: begin.command.clone(),
                target: begin.target.clone(),
                started_at: begin.started_at.clone(),
                finished_at: now.clone(),
                outcome: if status == ApplyStatus::Applied {
                    "applied".into()
                } else {
                    "applied-with-skips".into()
                },
                selection_before: begin.selection_before.clone(),
                selection_after: SelectionAfter {
                    text: begin.selection_after_text.clone(),
                },
                receipt_before: begin.receipt_before.clone(),
                receipt_after: receipt.to_value(),
            };
            write_history(fs, &ctx.state, &entry)?;
            history_written = true;
            fs.write_state(&ctx.state.applied(), receipt.to_text().as_bytes())?;
            runner.append(&Record::Receipt {
                outcome: if status == ApplyStatus::Applied {
                    MarkerOutcome::Clean
                } else {
                    MarkerOutcome::Skips
                },
            })?;
            fs.remove_state(&ctx.state.journal())?;
            if let Err(e) = prune_history(fs, &ctx.state, HISTORY_KEEP) {
                runner.warnings.push(Diagnostic::warning(
                    "history-prune-failed",
                    format!("cannot prune history: {e}"),
                ));
            }
        }
        ApplyStatus::Partial => {
            fs.write_state(&ctx.state.applied(), receipt.to_text().as_bytes())?;
            runner.append(&Record::Receipt {
                outcome: MarkerOutcome::Partial,
            })?;
        }
    }
    Ok((receipt, status, history_written))
}

/// Undo an interrupted apply (P10, G5, G6b): every non-skipped step in
/// reverse, decided by observing the disk; then created directories, the
/// receipt, the selection, the history entry, the journal, and the empty
/// state directories. Repeatable after a crash.
pub fn rollback(ctx: &ApplyCtx<'_>, fs: &dyn FsOps) -> Result<RecoverReport> {
    let j = present_journal(ctx)?;
    prepare_recovery(ctx, fs, &j)?;
    let begin = &j.begin;
    let dest_rel = ctx.adapter.destination();
    let op_id = begin.op_id.clone();
    let trash = ctx.state.trash_dir(&op_id)?;
    let mut warnings: Vec<Diagnostic> = Vec::new();
    let mut results = Vec::new();
    let mut left = false;
    let steps: Vec<Step> = begin.plan.iter().map(step_from_journal).collect();
    let ancestor = |dir: &str| -> Option<DestPath> {
        ctx.dest
            .ancestors()
            .into_iter()
            .find(|(rel, _)| rel == dir)
            .map(|(_, p)| p)
    };
    let child_of = |name: &str| -> Result<DestPath> {
        ctx.dest
            .join_child(name)
            .map_err(|reason| Error::JournalInvalid {
                path: ctx.state.journal().path().to_path_buf(),
                reason: format!("step name {name:?}: {reason}"),
            })
    };
    for step in steps.iter().rev() {
        let n = step.n();
        if matches!(j.states.get(&n), Some(StepState::Skipped { .. })) {
            continue;
        }
        match step {
            Step::Add {
                name,
                strategy,
                source,
                tree_hash,
                ..
            } => {
                let child = child_of(name)?;
                let want_hash = *strategy == crate::config::Strategy::Copy;
                let obs = observe_one(&child, want_hash)?;
                if obs == ObservedKind::Missing {
                    continue;
                }
                let src_text = source.to_string_lossy().into_owned();
                if matches_expectation(&obs, *strategy, &src_text, tree_hash) {
                    let expect = OwnedExpectation {
                        strategy: *strategy,
                        source: src_text,
                        tree_hash: Some(tree_hash.clone()),
                    };
                    let outcome = match fs.remove_owned(&child, &expect, &trash)? {
                        RemoveOutcome::Removed => StepOutcome::Done,
                        RemoveOutcome::RemovedWithResidue { trash } => {
                            warnings.push(Diagnostic::warning(
                                "trash-residue",
                                format!(
                                    "{} was removed; content not covered by its hash was left in {}",
                                    child.rel(),
                                    trash.display()
                                ),
                            ));
                            StepOutcome::Done
                        }
                        RemoveOutcome::Skipped(r) => {
                            left = true;
                            warnings.push(Diagnostic::warning(
                                "rollback-left",
                                format!("{} was left in place ({})", child.rel(), r.code()),
                            ));
                            StepOutcome::Skipped(r)
                        }
                    };
                    results.push(result_of(step, dest_rel, outcome));
                } else {
                    left = true;
                    warnings.push(Diagnostic::warning(
                        "rollback-left",
                        format!(
                            "{} holds content unam did not place in this operation; it is left untouched",
                            child.rel()
                        ),
                    ));
                    results.push(result_of(
                        step,
                        dest_rel,
                        StepOutcome::Skipped(SkipReason::Modified),
                    ));
                }
            }
            Step::Remove {
                id, name, expect, ..
            } => {
                let child = child_of(name)?;
                if observe_one(&child, false)? != ObservedKind::Missing {
                    continue;
                }
                let live = live_source(ctx.catalog, id, expect);
                match fs.restore_owned(&child, expect, &trash, live.as_ref(), &op_id)? {
                    RestoreOutcome::Restored => {
                        results.push(result_of(step, dest_rel, StepOutcome::Done));
                    }
                    RestoreOutcome::NotRestored(reason) => {
                        left = true;
                        warnings.push(Diagnostic::warning(
                            "rollback-not-restored",
                            format!("{} could not be restored: {reason}", child.rel()),
                        ));
                        results.push(result_of(
                            step,
                            dest_rel,
                            StepOutcome::Failed {
                                code: "rollback-not-restored".into(),
                                message: reason,
                            },
                        ));
                    }
                }
            }
            Step::DropOrphan { .. } | Step::UpdateProvenance { .. } => {}
            Step::RemoveDir { dir, .. } => {
                if let Some(p) = ancestor(dir)
                    && std::fs::symlink_metadata(p.path()).is_err()
                {
                    // Recreate the parents first (shallowest first).
                    for (rel, a) in ctx.dest.ancestors() {
                        if std::fs::symlink_metadata(a.path()).is_err() {
                            fs.create_dir(&a)?;
                        }
                        if rel == *dir {
                            break;
                        }
                    }
                    results.push(result_of(step, dest_rel, StepOutcome::Done));
                }
            }
        }
    }
    // Directories this operation created, deepest first.
    for dir in j.dirs_created.iter().rev() {
        if let Some(p) = ancestor(dir) {
            fs.rmdir_if_empty(&p)?;
        }
    }
    // The receipt.
    let current = load_receipt_opt(ctx)?;
    let before_last = j.receipt_before.as_ref().and_then(|r| r.last_op_id.clone());
    let restorable = match &current {
        None => true,
        Some(c) => c.last_op_id.as_deref() == Some(op_id.as_str()) || c.last_op_id == before_last,
    };
    if restorable {
        match &j.receipt_before {
            None => {
                if current.is_some() {
                    fs.remove_state(&ctx.state.applied())?;
                }
            }
            Some(r) => fs.write_state(&ctx.state.applied(), r.to_text().as_bytes())?,
        }
    } else {
        warnings.push(Diagnostic::warning(
            "receipt-not-restored",
            "the receipt was changed after the interrupted apply; it is left as it is",
        ));
    }
    // The selection (G11).
    restore_selection(ctx, fs, begin, &mut warnings)?;
    // The history entry of the undone apply (G6b).
    let hist = ctx.state.history_file(&op_id)?;
    if std::fs::symlink_metadata(hist.path()).is_ok() {
        fs.remove_state(&hist)?;
    }
    fs.remove_state(&ctx.state.journal())?;
    // G5: empty state directories, bottom-up; `.unam` stays (the lock).
    for d in [
        trash.clone(),
        ctx.state.trash_root(),
        ctx.state.history_dir(),
        ctx.state.dir(),
    ] {
        fs.remove_state_dir_if_empty(&d)?;
    }
    let receipt = load_receipt_opt(ctx)?;
    Ok(RecoverReport {
        action: "rollback",
        op_id,
        command: begin.command.clone(),
        results,
        status: if left {
            ApplyStatus::Partial
        } else {
            ApplyStatus::Applied
        },
        receipt,
        warnings,
        removal_applied: false,
        refresh: None,
    })
}

/// The pure diff (spec 4.8; the classification table of P7).
pub fn diff(input: &DiffInput<'_>) -> Plan {
    let dest_rel = input.header.dest_rel.as_str();
    let dest = |name: &str| format!("{dest_rel}/{name}");
    let mut conflicts: Vec<Conflict> = Vec::new();
    let mut warnings: Vec<Diagnostic> = Vec::new();

    // 1. Names.
    let mut valid: Vec<&DesiredEntry> = Vec::new();
    for d in input.desired {
        match validate_dest_name(&d.name) {
            Ok(()) => valid.push(d),
            Err(reason) => conflicts.push(Conflict::InvalidName {
                id: d.id.to_string(),
                name: d.name.clone(),
                reason,
            }),
        }
    }
    let mut by_name: BTreeMap<&str, Vec<&DesiredEntry>> = BTreeMap::new();
    for d in &valid {
        by_name.entry(d.name.as_str()).or_default().push(d);
    }
    let mut dup_reported: BTreeSet<&str> = BTreeSet::new();
    let mut remaining: Vec<&DesiredEntry> = Vec::new();
    for d in &valid {
        let group = &by_name[d.name.as_str()];
        if group.len() > 1 {
            if dup_reported.insert(d.name.as_str()) {
                conflicts.push(Conflict::DuplicateName {
                    name: d.name.clone(),
                    ids: group.iter().map(|x| x.id.to_string()).collect(),
                });
            }
        } else {
            remaining.push(d);
        }
    }

    // 2. Root state.
    let root_blocked = match &input.observed.dest_root {
        DestRootState::Outside { resolved } => {
            conflicts.push(Conflict::DestOutsideProject {
                dest_root: dest_rel.to_string(),
                resolved: resolved.clone(),
            });
            true
        }
        DestRootState::NotDir => {
            conflicts.push(Conflict::DestNotDirectory {
                dest_root: dest_rel.to_string(),
            });
            true
        }
        _ => false,
    };

    // 3. Receipt view.
    let mut view: BTreeMap<&str, &SkillEntry> = BTreeMap::new();
    let mut inconsistent = 0usize;
    for e in input.receipt.skill_entries() {
        if !e.consistent(dest_rel) {
            inconsistent += 1;
            warnings.push(Diagnostic::warning(
                "receipt-entry-ignored",
                format!(
                    "receipt entry {} ({}) does not match the destination; it is carried and never touched",
                    e.skill_id, e.dest
                ),
            ));
            continue;
        }
        if view.contains_key(e.name.as_str()) {
            inconsistent += 1;
            warnings.push(Diagnostic::warning(
                "receipt-entry-ignored",
                format!(
                    "receipt entry {} repeats the destination {}; the second entry is ignored",
                    e.skill_id, e.dest
                ),
            ));
            continue;
        }
        view.insert(e.name.as_str(), e);
    }

    // 4. Classification.
    let mut removes: Vec<Step> = Vec::new();
    let mut drops: Vec<Step> = Vec::new();
    let mut adds: Vec<Step> = Vec::new();
    let mut updates: Vec<Step> = Vec::new();
    let mut unchanged: Vec<PlanEntry> = Vec::new();
    let mut matched: BTreeSet<&str> = BTreeSet::new();
    let mut shown: BTreeSet<String> = BTreeSet::new();
    let make_add = |d: &DesiredEntry| -> Option<Step> {
        let skill = input.catalog.skill(&d.id)?;
        let source = input.catalog.abs_path(&d.id)?;
        Some(Step::Add {
            n: 0,
            id: d.id.to_string(),
            name: d.name.clone(),
            strategy: d.strategy,
            source,
            tree_hash: skill.tree_hash.clone(),
            provenance: canonical_provenance(&d.provenance),
        })
    };
    for d in &remaining {
        let name = d.name.as_str();
        let obs = input.observed.kind(name);
        let id = d.id.to_string();
        let r = view.get(name).copied();
        if r.is_some() {
            matched.insert(name);
        }
        let want_prov = canonical_provenance(&d.provenance);
        match r {
            None => {
                if obs == ObservedKind::Missing {
                    if let Some(s) = make_add(d) {
                        adds.push(s);
                        shown.insert(d.name.clone());
                    }
                } else {
                    conflicts.push(Conflict::ForeignAtDest {
                        dest: dest(name),
                        found: found_text(&obs).to_string(),
                        source: input
                            .catalog
                            .abs_path(&d.id)
                            .map(|p| p.to_string_lossy().into_owned())
                            .unwrap_or_default(),
                        id,
                    });
                }
            }
            Some(r) => {
                if obs == ObservedKind::Missing {
                    if let Some(s) = make_add(d) {
                        adds.push(s);
                        shown.insert(d.name.clone());
                    }
                } else if is_owned(r, &obs) {
                    if r.skill_id == id && r.strategy == d.strategy {
                        if canonical_provenance(&r.provenance) == want_prov {
                            unchanged.push(PlanEntry {
                                id: id.clone(),
                                name: d.name.clone(),
                                dest: dest(name),
                            });
                            if r.strategy == Strategy::Symlink
                                && let ObservedKind::Symlink {
                                    resolves: false, ..
                                } = &obs
                                && let Some(live) = input.catalog.abs_path(&d.id)
                                && live.to_string_lossy() != r.source_path
                            {
                                warnings.push(Diagnostic::info(
                                    "source-moved",
                                    format!(
                                        "{} links to {}, which no longer resolves; the source now lives at {}",
                                        dest(name),
                                        r.source_path,
                                        live.display()
                                    ),
                                ));
                            }
                        } else {
                            updates.push(Step::UpdateProvenance {
                                n: 0,
                                id: id.clone(),
                                name: d.name.clone(),
                                provenance: want_prov,
                            });
                        }
                        shown.insert(d.name.clone());
                    } else {
                        removes.push(Step::Remove {
                            n: 0,
                            id: r.skill_id.clone(),
                            name: r.name.clone(),
                            expect: expectation_of(r),
                        });
                        if let Some(s) = make_add(d) {
                            adds.push(s);
                            shown.insert(d.name.clone());
                        }
                    }
                } else {
                    conflicts.push(Conflict::ModifiedAtDest {
                        dest: dest(name),
                        id,
                        found: found_text(&obs).to_string(),
                    });
                }
            }
        }
    }

    // 5. Receipt entries no longer desired.
    let mut carried: Vec<PlanEntry> = Vec::new();
    let mut remaining_valid = 0usize;
    for (name, r) in &view {
        if matched.contains(name) {
            remaining_valid += 1;
            continue;
        }
        if input.carry_ids.contains(&r.skill_id) {
            carried.push(PlanEntry {
                id: r.skill_id.clone(),
                name: r.name.clone(),
                dest: r.dest.clone(),
            });
            warnings.push(Diagnostic::warning(
                "owned-source-unreachable",
                format!(
                    "{} ({}) is still selected but its source is unreachable; it is kept as it is",
                    r.dest, r.skill_id
                ),
            ));
            remaining_valid += 1;
            continue;
        }
        let obs = input.observed.kind(name);
        if obs == ObservedKind::Missing {
            drops.push(Step::DropOrphan {
                n: 0,
                id: r.skill_id.clone(),
                name: r.name.clone(),
                reason: OrphanReason::Missing,
            });
        } else if is_owned(r, &obs) {
            removes.push(Step::Remove {
                n: 0,
                id: r.skill_id.clone(),
                name: r.name.clone(),
                expect: expectation_of(r),
            });
        } else {
            drops.push(Step::DropOrphan {
                n: 0,
                id: r.skill_id.clone(),
                name: r.name.clone(),
                reason: OrphanReason::Modified,
            });
        }
    }

    // 6. Order and number.
    removes.sort_by(|a, b| {
        a.name()
            .unwrap_or("")
            .as_bytes()
            .cmp(b.name().unwrap_or("").as_bytes())
    });
    drops.sort_by(|a, b| {
        a.name()
            .unwrap_or("")
            .as_bytes()
            .cmp(b.name().unwrap_or("").as_bytes())
    });
    let mut steps: Vec<Step> = Vec::new();
    steps.extend(removes);
    steps.extend(drops);
    steps.extend(adds);
    steps.extend(updates);

    // 10. Created directories (deactivate only).
    if input.release_created_dirs {
        let prefixes = dest_prefixes(dest_rel);
        let mut valid_dirs: Vec<&String> = Vec::new();
        for d in &input.receipt.created_dirs {
            if prefixes.contains(d) {
                valid_dirs.push(d);
            } else {
                warnings.push(Diagnostic::warning(
                    "receipt-entry-ignored",
                    format!("created directory claim {d:?} is not a destination prefix; ignored"),
                ));
            }
        }
        if remaining_valid + inconsistent == 0 {
            for d in valid_dirs.into_iter().rev() {
                steps.push(Step::RemoveDir {
                    n: 0,
                    dir: d.clone(),
                });
            }
        }
    }
    if root_blocked {
        steps.clear();
    }
    for (i, s) in steps.iter_mut().enumerate() {
        s.set_n(u32::try_from(i + 1).unwrap_or(u32::MAX));
    }

    // 7. Warnings: shadows, budget.
    for sh in &input.observed.shadows {
        if shown.contains(&sh.name) {
            warnings.push(
                Diagnostic::warning(
                    "shadowed",
                    format!(
                        "{} is shadowed by {} ({} scope wins)",
                        sh.name,
                        sh.by.display(),
                        sh.scope.as_str()
                    ),
                )
                .with_path(sh.by.to_string_lossy().into_owned()),
            );
        }
    }

    // 8. Estimate.
    let mut tokens: u64 = 0;
    for d in input.desired {
        let desc = input
            .catalog
            .skill(&d.id)
            .map(|s| s.description.len())
            .unwrap_or(0);
        tokens += ceil_div4(d.name.len() + desc) + 20;
    }
    for c in &carried {
        tokens += ceil_div4(c.name.len()) + 20;
    }
    let estimate = Estimate {
        skills: input.desired.len() + carried.len(),
        tokens,
    };
    if tokens > u64::from(input.budget_tokens) {
        warnings.push(Diagnostic::warning(
            "catalog-over-budget",
            format!(
                "the estimated catalog is ~{tokens} tokens, over the budget of {} (estimate)",
                input.budget_tokens
            ),
        ));
    }

    // 9. Directories to create.
    let has_add = steps.iter().any(|s| matches!(s, Step::Add { .. }));
    let dest_dirs_to_create = match &input.observed.dest_root {
        DestRootState::Missing { to_create } if has_add => to_create.clone(),
        _ => Vec::new(),
    };

    Plan {
        header: input.header.clone(),
        op_id: input.op_id.clone(),
        steps,
        unchanged,
        carried,
        conflicts,
        warnings,
        estimate,
        selection_hash: input.selection_hash.clone(),
        dest_dirs_to_create,
    }
}
